<?php
/** Orchard Ledger offer transition endpoint: role ownership, availability, order creation, history, and notifications are one transaction. */
declare(strict_types=1);
require_once __DIR__ . '/../../includes/bootstrap.php';
require_method('POST');verify_csrf();$actor=require_login();$offerId=filter_input(INPUT_POST,'offer_id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$action=normalize_text($_POST['action']??'',20);
if(!$offerId||!in_array($action,['accept','reject','counter'],true))json_response(false,'Choose a valid offer action.',[],422);
$pdo=db();$pdo->beginTransaction();
try{$offer=fetch_one('SELECT o.*,pl.title,pl.quantity_available,pl.unit,pl.category_id,pl.status AS listing_status FROM offers o JOIN produce_listings pl ON pl.id=o.listing_id WHERE o.id=:id FOR UPDATE',['id'=>$offerId]);if($offer===null)throw new RuntimeException('This offer could not be found.');$isFarmer=$actor['role_slug']==='farmer'&&(int)$offer['farmer_id']===(int)$actor['id'];$isBuyer=$actor['role_slug']==='buyer'&&(int)$offer['buyer_id']===(int)$actor['id'];if(!$isFarmer&&!$isBuyer)throw new RuntimeException('You are not authorized to respond to this offer.');if($action==='counter'){if(!$isFarmer||!in_array($offer['status'],['pending','countered'],true))throw new RuntimeException('Only the listing farmer may counter a pending offer.');$quantity=positive_decimal($_POST['quantity']??null);$price=positive_decimal($_POST['offered_price']??null);if($quantity===null||$price===null||$quantity>(float)$offer['quantity_available'])throw new RuntimeException('Counter terms must use a positive quantity within current availability and a positive price.');$total=round($quantity*$price,2);$pdo->prepare('UPDATE offers SET quantity=:quantity,offered_price=:price,total_amount=:total,status="countered",responded_at=NOW() WHERE id=:id')->execute(['quantity'=>$quantity,'price'=>$price,'total'=>$total,'id'=>$offerId]);$pdo->prepare('INSERT INTO offer_events (offer_id,actor_user_id,event_type,quantity,price,note) VALUES (:offer,:actor,"countered",:quantity,:price,:note)')->execute(['offer'=>$offerId,'actor'=>$actor['id'],'quantity'=>$quantity,'price'=>$price,'note'=>'Farmer counterproposal sent.']);create_notification((int)$offer['buyer_id'],'offer_countered','Farmer counterproposal','New terms are available for '.$offer['title'].'.','buyer/offers.php','offer',$offerId);$pdo->commit();json_response(true,'Counter terms sent to the buyer.',['offer_id'=>$offerId,'redirect'=>app_url('farmer/offers.php')]);}
if($action==='reject'){if(($isFarmer&&!in_array($offer['status'],['pending','countered'],true))||($isBuyer&&$offer['status']!=='countered'))throw new RuntimeException('This offer cannot be declined in its current status.');$recipient=$isFarmer?(int)$offer['buyer_id']:(int)$offer['farmer_id'];$pdo->prepare('UPDATE offers SET status="rejected",responded_at=NOW() WHERE id=:id')->execute(['id'=>$offerId]);$pdo->prepare('INSERT INTO offer_events (offer_id,actor_user_id,event_type,note) VALUES (:offer,:actor,"rejected",:note)')->execute(['offer'=>$offerId,'actor'=>$actor['id'],'note'=>'Offer rejected.']);create_notification($recipient,'offer_rejected','Offer not accepted','The offer for '.$offer['title'].' was not accepted.',$isFarmer?'buyer/offers.php':'farmer/offers.php','offer',$offerId);$pdo->commit();json_response(true,'Offer status updated to rejected.',['offer_id'=>$offerId,'redirect'=>app_url($isFarmer?'farmer/offers.php':'buyer/offers.php')]);}
if(($isFarmer&&!in_array($offer['status'],['pending','countered'],true))||($isBuyer&&$offer['status']!=='countered'))throw new RuntimeException('This offer cannot be accepted in its current status.');if($offer['listing_status']!=='active'||(float)$offer['quantity']>(float)$offer['quantity_available'])throw new RuntimeException('Current listing availability cannot fulfil this offer.');$reference=generate_reference('QAL');$total=(float)$offer['total_amount'];$pdo->prepare('UPDATE offers SET status="accepted",responded_at=NOW() WHERE id=:id')->execute(['id'=>$offerId]);$pdo->prepare('INSERT INTO offer_events (offer_id,actor_user_id,event_type,quantity,price,note) VALUES (:offer,:actor,"accepted",:quantity,:price,:note)')->execute(['offer'=>$offerId,'actor'=>$actor['id'],'quantity'=>$offer['quantity'],'price'=>$offer['offered_price'],'note'=>'Offer accepted; order created.']);$pdo->prepare('INSERT INTO orders (reference_code,offer_id,buyer_id,farmer_id,status,subtotal,total_amount,confirmed_at) VALUES (:reference,:offer,:buyer,:farmer,"confirmed",:subtotal,:total,NOW())')->execute(['reference'=>$reference,'offer'=>$offerId,'buyer'=>$offer['buyer_id'],'farmer'=>$offer['farmer_id'],'subtotal'=>$total,'total'=>$total]);$orderId=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO order_items (order_id,listing_id,category_id,produce_name,grade,quantity,unit,unit_price,line_total) SELECT :order,pl.id,pl.category_id,pl.title,pl.grade,:quantity,pl.unit,:price,:total FROM produce_listings pl WHERE pl.id=:listing')->execute(['order'=>$orderId,'quantity'=>$offer['quantity'],'price'=>$offer['offered_price'],'total'=>$total,'listing'=>$offer['listing_id']]);$pdo->prepare('INSERT INTO order_status_history (order_id,status,changed_by_user_id,notes) VALUES (:order,"confirmed",:actor,:note)')->execute(['order'=>$orderId,'actor'=>$actor['id'],'note'=>'Order created from accepted offer.']);$pdo->prepare('UPDATE produce_listings SET quantity_available=quantity_available-:deduct_quantity,status=CASE WHEN quantity_available-:remaining_quantity<=0 THEN "sold_out" ELSE status END WHERE id=:listing')->execute(['deduct_quantity'=>$offer['quantity'],'remaining_quantity'=>$offer['quantity'],'listing'=>$offer['listing_id']]);$recipient=$isFarmer?(int)$offer['buyer_id']:(int)$offer['farmer_id'];create_notification($recipient,'offer_accepted','Offer accepted','Order '.$reference.' has been created for '.$offer['title'].'.',$isFarmer?'buyer/offers.php':'farmer/offers.php','order',$orderId);$pdo->commit();audit_log((int)$actor['id'],'offer_accepted','orders',$orderId,['offer_id'=>$offerId,'reference'=>$reference]);json_response(true,'Offer accepted and order '.$reference.' created.',['offer_id'=>$offerId,'order_id'=>$orderId,'reference'=>$reference,'redirect'=>app_url($isFarmer?'farmer/offers.php':'buyer/offers.php')]);
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();json_response(false,$e instanceof RuntimeException?$e->getMessage():'The offer could not be updated. Please try again.',[],422);}
